  ('e2000000-0000-4000-a000-0000000011a6', 'CO-FIS-00073', 6, 176, 'medio', 2, 62, 2026, 'multiple_choice', 'Lei de Hooke', 'Uma mola de constante elástica 700 N/m é esticada em 5 cm. Qual é a força elástica?', 'Lei de Hooke: F = k·x, com x em metros. 5 cm = 0,05 m; F = 700·0,05 = 35 N.', 'F = k·x, sempre com x em metros.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000011a7', 'CO-FIS-00074', 6, 179, 'medio', 4, 62, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 3 atm, ocupa 20 L e tem temperatura de 127 °C. Ele passa a 3 atm e 19 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 127 + 273 = 400 K. T₂ = 3·19·400/(3·20) = 380 K = 107 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000011a8', 'CO-FIS-00075', 6, 179, 'medio', 4, 62, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 2 atm, ocupa 7 L e tem temperatura de 77 °C. Ele passa a 5 atm e 2 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 77 + 273 = 350 K. T₂ = 5·2·350/(2·7) = 250 K = -23 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000011a9', 'CO-FIS-00076', 6, 179, 'medio', 4, 62, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 2 atm, ocupa 10 L e tem temperatura de 127 °C. Ele passa a 2 atm e 5 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 127 + 273 = 400 K. T₂ = 2·5·400/(2·10) = 200 K = -73 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000011aa', 'CO-FIS-00077', 6, 179, 'medio', 4, 62, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 4 atm, ocupa 4 L e tem temperatura de 227 °C. Ele passa a 5 atm e 4 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 227 + 273 = 500 K. T₂ = 5·4·500/(4·4) = 625 K = 352 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
