  ('e2000000-0000-4000-a000-0000000011f2', 'CO-QUI-00016', 7, 192, 'medio', 2, 62, 2026, 'multiple_choice', 'Constante de Avogadro', 'Quantas moléculas existem em 23 g de etanol (C₂H₆O)? (M = 46 g/mol; constante de Avogadro = 6 × 10²³ mol⁻¹.)', 'n = 23/46 = 0,5 mol. Moléculas = 0,5 × 6 × 10²³ = 3 × 10²³.', 'Primeiro ache os mols; depois multiplique por 6 × 10²³.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000011f3', 'CO-QUI-00017', 7, 192, 'medio', 2, 62, 2026, 'multiple_choice', 'Constante de Avogadro', 'Quantas moléculas existem em 292,5 g de cloreto de sódio (NaCl)? (M = 58,5 g/mol; constante de Avogadro = 6 × 10²³ mol⁻¹.)', 'n = 292,5/58,5 = 5 mol. Moléculas = 5 × 6 × 10²³ = 3 × 10²⁴.', 'Primeiro ache os mols; depois multiplique por 6 × 10²³.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000011f4', 'CO-QUI-00018', 7, 193, 'enem', 3, 62, 2026, 'multiple_choice', 'Concentração em mol/L', 'Dissolvem-se 73 g de ácido clorídrico (HCl) em água até completar 500 mL de solução. Qual é a concentração em mol/L? (M = 36,5 g/mol.)', 'n = 73/36,5 = 2 mol. Volume = 0,5 L. Concentração = 2/0,5 = 4 mol/L.', 'Ache os mols do soluto e divida pelo volume em litros.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
