  ('e2000000-0000-4000-a000-000000001200', 'CO-QUI-00030', 7, 198, 'medio', 4, 62, 2026, 'multiple_choice', 'Mistura de soluções', 'Misturam-se 200 mL de uma solução de NaCl a 1,8 mol/L com 800 mL de outra solução de NaCl a 0,2 mol/L. Qual é a concentração da mistura?', 'C·V total = 1,8·200 + 0,2·800 = 520. Volume final = 1000 mL. C = 520/1000 = 0,52 mol/L.', 'Na mistura do mesmo soluto, C₁V₁ + C₂V₂ = C_f·(V₁ + V₂).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001201', 'CO-QUI-00031', 7, 198, 'medio', 4, 62, 2026, 'multiple_choice', 'Mistura de soluções', 'Misturam-se 400 mL de uma solução de NaCl a 0,1 mol/L com 1000 mL de outra solução de NaCl a 5 mol/L. Qual é a concentração da mistura?', 'C·V total = 0,1·400 + 5·1000 = 5.040. Volume final = 1400 mL. C = 5.040/1400 = 3,6 mol/L.', 'Na mistura do mesmo soluto, C₁V₁ + C₂V₂ = C_f·(V₁ + V₂).', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
