  ('e2000000-0000-4000-a000-000000001212', 'CO-QUI-00048', 7, 199, 'enem', 4, 62, 2026, 'multiple_choice', 'Rendimento de reação', 'Uma indústria calculou que, com a matéria-prima disponível, poderia obter no máximo 370 kg de amônia. Se o rendimento real do processo é de 50%, quanto amônia é efetivamente produzido?', 'Massa real = 370 × 0,5 = 185 kg.', 'Massa obtida = massa teórica × rendimento.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001213', 'CO-QUI-00049', 7, 201, 'medio', 4, 62, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 10 mL de uma solução de H₂SO₄, gastaram-se 42 mL de NaOH a 0,1 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 0,1 × 42/1000. Cada H₂SO₄ neutraliza 2 NaOH, então mols de ácido = metade. C = 0,1·42/(2·10) = 0,21 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001214', 'CO-QUI-00050', 7, 201, 'medio', 4, 62, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 25 mL de uma solução de HCl, gastaram-se 20 mL de NaOH a 0,1 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 0,1 × 20/1000. A proporção HCl : NaOH é 1 : 1. C = 0,1·20/(1·25) = 0,08 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001215', 'CO-QUI-00051', 7, 201, 'medio', 4, 62, 2026, 'multiple_choice', 'Titulação', 'Na titulação de 10 mL de uma solução de H₂SO₄, gastaram-se 26 mL de NaOH a 0,5 mol/L até a neutralização completa. Qual é a concentração do ácido?', 'Mols de NaOH = 0,5 × 26/1000. Cada H₂SO₄ neutraliza 2 NaOH, então mols de ácido = metade. C = 0,5·26/(2·10) = 0,65 mol/L.', 'No ponto de equivalência, mols de H⁺ = mols de OH⁻.', 'Questão autoral da Educa Mais no estilo do PAES/UEMA (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
