  ('e2000000-0000-4000-a000-00000000129c', 'CO-MAT-01212', 3, 149, 'medio', 4, 63, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (−1 − i)·(−5 + 3i) é igual a:', 'Aplicando a distributiva: (−1)·(−5) + (−1)·3i + (−1)·(−5)i + (−1)·3i². Como i² = −1, a parte real é 5 + 3 = 8 e a parte imaginária é 2i. Resultado: 8 + 2i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000129d', 'CO-MAT-01213', 3, 149, 'medio', 4, 63, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (−4 + 4i)·(−2 + 3i) é igual a:', 'Aplicando a distributiva: (−4)·(−2) + (−4)·3i + 4·(−2)i + 4·3i². Como i² = −1, a parte real é 8 − 12 = −4 e a parte imaginária é −20i. Resultado: −4 − 20i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000129e', 'CO-MAT-01214', 3, 149, 'medio', 4, 63, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (−5 + 4i)·(−1 − 6i) é igual a:', 'Aplicando a distributiva: (−5)·(−1) + (−5)·(−6)i + 4·(−1)i + 4·(−6)i². Como i² = −1, a parte real é 5 + 24 = 29 e a parte imaginária é 26i. Resultado: 29 + 26i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000129f', 'CO-MAT-01215', 3, 149, 'medio', 4, 63, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (4 − i)·(4 − 5i) é igual a:', 'Aplicando a distributiva: 4·4 + 4·(−5)i + (−1)·4i + (−1)·(−5)i². Como i² = −1, a parte real é 16 − 5 = 11 e a parte imaginária é −24i. Resultado: 11 − 24i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a0', 'CO-MAT-01216', 3, 149, 'medio', 4, 63, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (−6 − 2i)·(−3 + 2i) é igual a:', 'Aplicando a distributiva: (−6)·(−3) + (−6)·2i + (−2)·(−3)i + (−2)·2i². Como i² = −1, a parte real é 18 + 4 = 22 e a parte imaginária é −6i. Resultado: 22 − 6i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a1', 'CO-MAT-01217', 3, 149, 'medio', 4, 63, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (−6 + 3i)·(−1 − 3i) é igual a:', 'Aplicando a distributiva: (−6)·(−1) + (−6)·(−3)i + 3·(−1)i + 3·(−3)i². Como i² = −1, a parte real é 6 + 9 = 15 e a parte imaginária é 15i. Resultado: 15 + 15i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a2', 'CO-MAT-01218', 3, 149, 'medio', 4, 63, 2026, 'multiple_choice', 'Operações com complexos', 'Sendo i a unidade imaginária (i² = −1), o produto (5 − i)·(2 − 4i) é igual a:', 'Aplicando a distributiva: 5·2 + 5·(−4)i + (−1)·2i + (−1)·(−4)i². Como i² = −1, a parte real é 10 − 4 = 6 e a parte imaginária é −22i. Resultado: 6 − 22i.', 'Multiplique como polinômios e troque i² por −1.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a3', 'CO-MAT-01219', 3, 152, 'medio', 3, 63, 2026, 'multiple_choice', 'Distância entre pontos', 'No plano cartesiano, qual é a distância entre os pontos A(6, 5) e B(−2, 11)?', 'd = √[(x₂ − x₁)² + (y₂ − y₁)²] = √(8² + 6²) = √100 = 10.', 'A distância é a hipotenusa de um triângulo retângulo com catetos Δx e Δy.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a4', 'CO-MAT-01220', 3, 152, 'medio', 3, 63, 2026, 'multiple_choice', 'Distância entre pontos', 'No plano cartesiano, qual é a distância entre os pontos A(0, −5) e B(6, −13)?', 'd = √[(x₂ − x₁)² + (y₂ − y₁)²] = √(6² + 8²) = √100 = 10.', 'A distância é a hipotenusa de um triângulo retângulo com catetos Δx e Δy.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a5', 'CO-MAT-01221', 3, 152, 'medio', 3, 63, 2026, 'multiple_choice', 'Distância entre pontos', 'No plano cartesiano, qual é a distância entre os pontos A(6, −4) e B(18, 1)?', 'd = √[(x₂ − x₁)² + (y₂ − y₁)²] = √(12² + 5²) = √169 = 13.', 'A distância é a hipotenusa de um triângulo retângulo com catetos Δx e Δy.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a6', 'CO-MAT-01222', 3, 152, 'medio', 3, 63, 2026, 'multiple_choice', 'Distância entre pontos', 'No plano cartesiano, qual é a distância entre os pontos A(−5, −3) e B(−11, 5)?', 'd = √[(x₂ − x₁)² + (y₂ − y₁)²] = √(6² + 8²) = √100 = 10.', 'A distância é a hipotenusa de um triângulo retângulo com catetos Δx e Δy.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a7', 'CO-MAT-01223', 3, 152, 'medio', 3, 63, 2026, 'multiple_choice', 'Distância entre pontos', 'No plano cartesiano, qual é a distância entre os pontos A(−1, 3) e B(4, 15)?', 'd = √[(x₂ − x₁)² + (y₂ − y₁)²] = √(5² + 12²) = √169 = 13.', 'A distância é a hipotenusa de um triângulo retângulo com catetos Δx e Δy.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a8', 'CO-MAT-01224', 3, 152, 'medio', 3, 63, 2026, 'multiple_choice', 'Distância entre pontos', 'No plano cartesiano, qual é a distância entre os pontos A(1, −3) e B(13, −8)?', 'd = √[(x₂ − x₁)² + (y₂ − y₁)²] = √(12² + 5²) = √169 = 13.', 'A distância é a hipotenusa de um triângulo retângulo com catetos Δx e Δy.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012a9', 'CO-MAT-01225', 3, 153, 'medio', 3, 63, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (−2, −15) e (2, 5)?', 'Coeficiente angular: m = (5 − −15)/(2 − −2) = 5. Substituindo (−2, −15) em y = 5x + n: n = −5. Logo, y = 5x − 5.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012aa', 'CO-MAT-01226', 3, 153, 'medio', 3, 63, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (−4, 1) e (0, 9)?', 'Coeficiente angular: m = (9 − 1)/(0 − −4) = 2. Substituindo (−4, 1) em y = 2x + n: n = 9. Logo, y = 2x + 9.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ab', 'CO-MAT-01227', 3, 153, 'medio', 3, 63, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (−1, 5) e (2, 2)?', 'Coeficiente angular: m = (2 − 5)/(2 − −1) = −1. Substituindo (−1, 5) em y = −1x + n: n = 4. Logo, y = −x + 4.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ac', 'CO-MAT-01228', 3, 153, 'medio', 3, 63, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (−2, −2) e (1, −8)?', 'Coeficiente angular: m = (−8 − −2)/(1 − −2) = −2. Substituindo (−2, −2) em y = −2x + n: n = −6. Logo, y = −2x − 6.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ad', 'CO-MAT-01229', 3, 153, 'medio', 3, 63, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (3, −10) e (6, −19)?', 'Coeficiente angular: m = (−19 − −10)/(6 − 3) = −3. Substituindo (3, −10) em y = −3x + n: n = −1. Logo, y = −3x − 1.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ae', 'CO-MAT-01230', 3, 153, 'medio', 3, 63, 2026, 'multiple_choice', 'Equação da reta', 'Qual é a equação da reta que passa pelos pontos (0, −2) e (2, −12)?', 'Coeficiente angular: m = (−12 − −2)/(2 − 0) = −5. Substituindo (0, −2) em y = −5x + n: n = −2. Logo, y = −5x − 2.', 'Calcule m = Δy/Δx e depois use um dos pontos para achar o termo independente.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012af', 'CO-MAT-01231', 3, 154, 'enem', 2, 63, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma praça circular tem raio de 18 m. Usando π = 3, qual é o comprimento da sua borda (circunferência)?', 'C = 2·π·r = 2·3·18 = 108 m.', 'Comprimento da circunferência: 2·π·r.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b0', 'CO-MAT-01232', 3, 154, 'enem', 2, 63, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma pizza tem raio de 29 m. Usando π = 3, qual é o comprimento da sua borda (circunferência)?', 'C = 2·π·r = 2·3·29 = 174 m.', 'Comprimento da circunferência: 2·π·r.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b1', 'CO-MAT-01233', 3, 154, 'enem', 2, 63, 2026, 'multiple_choice', 'Círculo e circunferência', 'Um canteiro circular tem raio de 38 m. Usando π = 3, qual é a sua área?', 'A = π·r² = 3·38² = 4.332 m².', 'Área do círculo: π·r².', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b2', 'CO-MAT-01234', 3, 154, 'enem', 2, 63, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma praça circular tem raio de 20 m. Usando π = 3,14, qual é o comprimento da sua borda (circunferência)?', 'C = 2·π·r = 2·3,14·20 = 125,6 m.', 'Comprimento da circunferência: 2·π·r.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b3', 'CO-MAT-01235', 3, 154, 'enem', 2, 63, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma pizza tem raio de 25 m. Usando π = 3, qual é a sua área?', 'A = π·r² = 3·25² = 1.875 m².', 'Área do círculo: π·r².', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b4', 'CO-MAT-01236', 3, 154, 'enem', 2, 63, 2026, 'multiple_choice', 'Círculo e circunferência', 'Uma pizza tem raio de 19 m. Usando π = 3, qual é o comprimento da sua borda (circunferência)?', 'C = 2·π·r = 2·3·19 = 114 m.', 'Comprimento da circunferência: 2·π·r.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b5', 'CO-MAT-01237', 3, 156, 'enem', 3, 63, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Uma escada apoiada num muro tem 34 m de comprimento e forma um ângulo de 60° com o chão. Usando sen 60° ≈ 0,85 e cos 60° ≈ 0,5, a altura que o topo da escada alcança é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 60° = 34 × 0,85 = 28,9 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b6', 'CO-MAT-01238', 3, 156, 'enem', 3, 63, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Uma escada apoiada num muro tem 8 m de comprimento e forma um ângulo de 45° com o chão. Usando sen 45° ≈ 0,7 e cos 45° ≈ 0,7, a altura que o topo da escada alcança é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 45° = 8 × 0,7 = 5,6 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b7', 'CO-MAT-01239', 3, 156, 'enem', 3, 63, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Uma rampa tem 34 m de comprimento e forma um ângulo de 30° com o chão. Usando sen 30° ≈ 0,5 e cos 30° ≈ 0,85, a altura que ela vence é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 30° = 34 × 0,5 = 17 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b8', 'CO-MAT-01240', 3, 156, 'enem', 3, 63, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Um cabo esticado do alto de uma torre ao chão tem 6 m de comprimento e forma um ângulo de 45° com o chão. Usando sen 45° ≈ 0,7 e cos 45° ≈ 0,7, a altura da torre é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 45° = 6 × 0,7 = 4,2 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012b9', 'CO-MAT-01241', 3, 156, 'enem', 3, 63, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Uma escada apoiada num muro tem 32 m de comprimento e forma um ângulo de 60° com o chão. Usando sen 60° ≈ 0,85 e cos 60° ≈ 0,5, a altura que o topo da escada alcança é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 60° = 32 × 0,85 = 27,2 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ba', 'CO-MAT-01242', 3, 156, 'enem', 3, 63, 2026, 'multiple_choice', 'Trigonometria no triângulo retângulo', 'Um cabo esticado do alto de uma torre ao chão tem 22 m de comprimento e forma um ângulo de 30° com o chão. Usando sen 30° ≈ 0,5 e cos 30° ≈ 0,85, a altura da torre é de aproximadamente:', 'A altura é o cateto oposto ao ângulo: altura = comprimento × sen 30° = 22 × 0,5 = 11 m.', 'Cateto oposto = hipotenusa × seno; cateto adjacente = hipotenusa × cosseno.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012bb', 'CO-MAT-01243', 3, 157, 'enem', 3, 63, 2026, 'multiple_choice', 'Inequações do 1º grau', 'Uma estacionamento oferece dois planos: A, com taxa fixa de R$ 10,00 e R$ 9,50 por unidade, e B, com taxa fixa de R$ 135,00 e R$ 4,50 por unidade (as unidades são horas). A partir de quantas unidades o plano B passa a ser mais barato?', 'B < A ⇔ 135 + 4,5x < 10 + 9,5x ⇔ 5x > 125 ⇔ x > 25. O menor número inteiro é 26.', 'Monte a desigualdade custo B < custo A e isole x.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012bc', 'CO-MAT-01244', 3, 157, 'enem', 3, 63, 2026, 'multiple_choice', 'Inequações do 1º grau', 'Uma plano de celular oferece dois planos: A, com taxa fixa de R$ 20,00 e R$ 7,50 por unidade, e B, com taxa fixa de R$ 130,00 e R$ 6,00 por unidade (as unidades são gigabytes extras). A partir de quantas unidades o plano B passa a ser mais barato?', 'B < A ⇔ 130 + 6x < 20 + 7,5x ⇔ 1,5x > 110 ⇔ x > 73,33. O menor número inteiro é 74.', 'Monte a desigualdade custo B < custo A e isole x.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012bd', 'CO-MAT-01245', 3, 157, 'enem', 3, 63, 2026, 'multiple_choice', 'Inequações do 1º grau', 'Uma estacionamento oferece dois planos: A, com taxa fixa de R$ 20,00 e R$ 10,00 por unidade, e B, com taxa fixa de R$ 135,00 e R$ 5,50 por unidade (as unidades são horas). A partir de quantas unidades o plano B passa a ser mais barato?', 'B < A ⇔ 135 + 5,5x < 20 + 10x ⇔ 4,5x > 115 ⇔ x > 25,56. O menor número inteiro é 26.', 'Monte a desigualdade custo B < custo A e isole x.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012be', 'CO-MAT-01246', 3, 157, 'enem', 3, 63, 2026, 'multiple_choice', 'Inequações do 1º grau', 'Uma locadora de carros oferece dois planos: A, com taxa fixa de R$ 10,00 e R$ 8,00 por unidade, e B, com taxa fixa de R$ 165,00 e R$ 3,50 por unidade (as unidades são quilômetros). A partir de quantas unidades o plano B passa a ser mais barato?', 'B < A ⇔ 165 + 3,5x < 10 + 8x ⇔ 4,5x > 155 ⇔ x > 34,44. O menor número inteiro é 35.', 'Monte a desigualdade custo B < custo A e isole x.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012bf', 'CO-MAT-01247', 3, 157, 'enem', 3, 63, 2026, 'multiple_choice', 'Inequações do 1º grau', 'Uma locadora de carros oferece dois planos: A, com taxa fixa de R$ 10,00 e R$ 10,00 por unidade, e B, com taxa fixa de R$ 130,00 e R$ 1,50 por unidade (as unidades são quilômetros). A partir de quantas unidades o plano B passa a ser mais barato?', 'B < A ⇔ 130 + 1,5x < 10 + 10x ⇔ 8,5x > 120 ⇔ x > 14,12. O menor número inteiro é 15.', 'Monte a desigualdade custo B < custo A e isole x.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c0', 'CO-MAT-01248', 3, 157, 'enem', 3, 63, 2026, 'multiple_choice', 'Inequações do 1º grau', 'Uma estacionamento oferece dois planos: A, com taxa fixa de R$ 50,00 e R$ 8,50 por unidade, e B, com taxa fixa de R$ 185,00 e R$ 7,50 por unidade (as unidades são horas). A partir de quantas unidades o plano B passa a ser mais barato?', 'B < A ⇔ 185 + 7,5x < 50 + 8,5x ⇔ 1x > 135 ⇔ x > 135. O menor número inteiro é 136.', 'Monte a desigualdade custo B < custo A e isole x.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c1', 'CO-MAT-01249', 3, 159, 'enem', 2, 63, 2026, 'multiple_choice', 'Divisão proporcional', 'Letícia, Eduarda e Mariana investiram num negócio, respectivamente, nas proporções 3, 5 e 6. O lucro de R$ 40.600,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Mariana?', 'Total de partes: 3 + 5 + 6 = 14. Cada parte vale R$ 40.600,00/14 = R$ 2.900,00. Mariana recebe 6 × R$ 2.900,00 = R$ 17.400,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c2', 'CO-MAT-01250', 3, 159, 'enem', 2, 63, 2026, 'multiple_choice', 'Divisão proporcional', 'Lucas, Larissa e Carla investiram num negócio, respectivamente, nas proporções 1, 6 e 6. O lucro de R$ 27.300,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Lucas?', 'Total de partes: 1 + 6 + 6 = 13. Cada parte vale R$ 27.300,00/13 = R$ 2.100,00. Lucas recebe 1 × R$ 2.100,00 = R$ 2.100,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c3', 'CO-MAT-01251', 3, 159, 'enem', 2, 63, 2026, 'multiple_choice', 'Divisão proporcional', 'Bruno, Karina e Isabela investiram num negócio, respectivamente, nas proporções 5, 1 e 2. O lucro de R$ 12.000,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Isabela?', 'Total de partes: 5 + 1 + 2 = 8. Cada parte vale R$ 12.000,00/8 = R$ 1.500,00. Isabela recebe 2 × R$ 1.500,00 = R$ 3.000,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c4', 'CO-MAT-01252', 3, 159, 'enem', 2, 63, 2026, 'multiple_choice', 'Divisão proporcional', 'Ana, Henrique e Yasmin investiram num negócio, respectivamente, nas proporções 3, 1 e 4. O lucro de R$ 17.600,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Yasmin?', 'Total de partes: 3 + 1 + 4 = 8. Cada parte vale R$ 17.600,00/8 = R$ 2.200,00. Yasmin recebe 4 × R$ 2.200,00 = R$ 8.800,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c5', 'CO-MAT-01253', 3, 159, 'enem', 2, 63, 2026, 'multiple_choice', 'Divisão proporcional', 'Gabriela, Ana e Mariana investiram num negócio, respectivamente, nas proporções 4, 2 e 5. O lucro de R$ 28.600,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Ana?', 'Total de partes: 4 + 2 + 5 = 11. Cada parte vale R$ 28.600,00/11 = R$ 2.600,00. Ana recebe 2 × R$ 2.600,00 = R$ 5.200,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c6', 'CO-MAT-01254', 3, 159, 'enem', 2, 63, 2026, 'multiple_choice', 'Divisão proporcional', 'Pedro, Bruno e Mateus investiram num negócio, respectivamente, nas proporções 3, 1 e 5. O lucro de R$ 3.600,00 será dividido em partes diretamente proporcionais ao que cada um investiu. Quanto receberá Bruno?', 'Total de partes: 3 + 1 + 5 = 9. Cada parte vale R$ 3.600,00/9 = R$ 400,00. Bruno recebe 1 × R$ 400,00 = R$ 400,00.', 'Some as proporções, descubra quanto vale uma parte e multiplique.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c7', 'CO-MAT-01255', 3, 160, 'enem', 2, 63, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 1, prova 2 tem peso 2 e o trabalho tem peso 2. Pedro tirou 7, 4,5 e 8,5, nessa ordem. Qual foi a média final?', 'Média ponderada = (7·1 + 4,5·2 + 8,5·2)/(1 + 2 + 2) = 33/5 = 6,6.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c8', 'CO-MAT-01256', 3, 160, 'enem', 2, 63, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 1, prova 2 tem peso 2 e o trabalho tem peso 2. João tirou 4,5, 5 e 7, nessa ordem. Qual foi a média final?', 'Média ponderada = (4,5·1 + 5·2 + 7·2)/(1 + 2 + 2) = 28,5/5 = 5,7.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012c9', 'CO-MAT-01257', 3, 160, 'enem', 2, 63, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 3, prova 2 tem peso 3 e o trabalho tem peso 4. Olívia tirou 10, 10,5 e 9, nessa ordem. Qual foi a média final?', 'Média ponderada = (10·3 + 10,5·3 + 9·4)/(3 + 3 + 4) = 97,5/10 = 9,75.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ca', 'CO-MAT-01258', 3, 160, 'enem', 2, 63, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 2, prova 2 tem peso 3 e o trabalho tem peso 5. Pedro tirou 8, 7 e 10, nessa ordem. Qual foi a média final?', 'Média ponderada = (8·2 + 7·3 + 10·5)/(2 + 3 + 5) = 87/10 = 8,7.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012cb', 'CO-MAT-01259', 3, 160, 'enem', 2, 63, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 2, prova 2 tem peso 3 e o trabalho tem peso 5. Letícia tirou 10,5, 10 e 10,5, nessa ordem. Qual foi a média final?', 'Média ponderada = (10,5·2 + 10·3 + 10,5·5)/(2 + 3 + 5) = 103,5/10 = 10,35.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012cc', 'CO-MAT-01260', 3, 160, 'enem', 2, 63, 2026, 'multiple_choice', 'Média ponderada', 'Em uma escola, a média final é ponderada: prova 1 tem peso 2, prova 2 tem peso 3 e o trabalho tem peso 5. Lucas tirou 9,5, 4,5 e 3,5, nessa ordem. Qual foi a média final?', 'Média ponderada = (9,5·2 + 4,5·3 + 3,5·5)/(2 + 3 + 5) = 50/10 = 5.', 'Multiplique cada nota pelo seu peso, some e divida pela soma dos pesos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012cd', 'CO-MAT-01261', 3, 162, 'medio', 4, 63, 2026, 'multiple_choice', 'Teorema do resto', 'Qual é o resto da divisão do polinômio P(x) = −x³ − 2x² − 6x − 9 por (x + 1)?', 'Pelo teorema do resto, o resto é P(−1) = −1·(−1)³ − 2·(−1)² − 6·(−1) − 9 = −4.', 'O resto da divisão de P(x) por (x − a) é P(a).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ce', 'CO-MAT-01262', 3, 162, 'medio', 4, 63, 2026, 'multiple_choice', 'Teorema do resto', 'Qual é o resto da divisão do polinômio P(x) = 2x³ + 3x² + 3x + 4 por (x − 3)?', 'Pelo teorema do resto, o resto é P(3) = 2·(3)³ + 3·(3)² + 3·(3) + 4 = 94.', 'O resto da divisão de P(x) por (x − a) é P(a).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012cf', 'CO-MAT-01263', 3, 162, 'medio', 4, 63, 2026, 'multiple_choice', 'Teorema do resto', 'Qual é o resto da divisão do polinômio P(x) = x³ − 3x² + 3x + 4 por (x − 2)?', 'Pelo teorema do resto, o resto é P(2) = 1·(2)³ − 3·(2)² + 3·(2) + 4 = 6.', 'O resto da divisão de P(x) por (x − a) é P(a).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d0', 'CO-MAT-01264', 3, 162, 'medio', 4, 63, 2026, 'multiple_choice', 'Teorema do resto', 'Qual é o resto da divisão do polinômio P(x) = 3x³ − 2x² − 6x + 7 por (x − 3)?', 'Pelo teorema do resto, o resto é P(3) = 3·(3)³ − 2·(3)² − 6·(3) + 7 = 52.', 'O resto da divisão de P(x) por (x − a) é P(a).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d1', 'CO-MAT-01265', 3, 162, 'medio', 4, 63, 2026, 'multiple_choice', 'Teorema do resto', 'Qual é o resto da divisão do polinômio P(x) = 3x³ − 4x² + 2x − 2 por (x − 1)?', 'Pelo teorema do resto, o resto é P(1) = 3·(1)³ − 4·(1)² + 2·(1) − 2 = −1.', 'O resto da divisão de P(x) por (x − a) é P(a).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d2', 'CO-MAT-01266', 3, 162, 'medio', 4, 63, 2026, 'multiple_choice', 'Teorema do resto', 'Qual é o resto da divisão do polinômio P(x) = 3x³ + 5x² − 2x + 9 por (x − 3)?', 'Pelo teorema do resto, o resto é P(3) = 3·(3)³ + 5·(3)² − 2·(3) + 9 = 129.', 'O resto da divisão de P(x) por (x − a) é P(a).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d3', 'CO-MAT-01267', 3, 162, 'medio', 4, 63, 2026, 'multiple_choice', 'Teorema do resto', 'Qual é o resto da divisão do polinômio P(x) = −3x³ + 4x − 3 por (x − 1)?', 'Pelo teorema do resto, o resto é P(1) = −3·(1)³ + 0·(1)² + 4·(1) − 3 = −2.', 'O resto da divisão de P(x) por (x − a) é P(a).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d4', 'CO-MAT-01268', 3, 163, 'medio', 5, 63, 2026, 'multiple_choice', 'Relações de Girard', 'Sejam r₁, r₂ e r₃ as raízes (reais ou complexas) da equação 4x³ − 7x² + x − 4 = 0. Qual é a soma dos produtos dois a dois das raízes?', 'Pelas relações de Girard para ax³ + bx² + cx + d = 0: soma = −b/a, soma dos produtos dois a dois = c/a, produto = −d/a. Aqui a = 4, b = -7, c = 1, d = -4, então a soma dos produtos dois a dois é 1/4.', 'Girard: r₁ + r₂ + r₃ = −b/a; r₁r₂ + r₁r₃ + r₂r₃ = c/a; r₁r₂r₃ = −d/a.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d5', 'CO-MAT-01269', 3, 163, 'medio', 5, 63, 2026, 'multiple_choice', 'Relações de Girard', 'Sejam r₁, r₂ e r₃ as raízes (reais ou complexas) da equação −x³ + 9x² + 7x + 8 = 0. Qual é a soma das raízes?', 'Pelas relações de Girard para ax³ + bx² + cx + d = 0: soma = −b/a, soma dos produtos dois a dois = c/a, produto = −d/a. Aqui a = -1, b = 9, c = 7, d = 8, então a soma é 9.', 'Girard: r₁ + r₂ + r₃ = −b/a; r₁r₂ + r₁r₃ + r₂r₃ = c/a; r₁r₂r₃ = −d/a.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d6', 'CO-MAT-01270', 3, 163, 'medio', 5, 63, 2026, 'multiple_choice', 'Relações de Girard', 'Sejam r₁, r₂ e r₃ as raízes (reais ou complexas) da equação −4x³ + 6x² − 9x − 6 = 0. Qual é a soma das raízes?', 'Pelas relações de Girard para ax³ + bx² + cx + d = 0: soma = −b/a, soma dos produtos dois a dois = c/a, produto = −d/a. Aqui a = -4, b = 6, c = -9, d = -6, então a soma é 3/2.', 'Girard: r₁ + r₂ + r₃ = −b/a; r₁r₂ + r₁r₃ + r₂r₃ = c/a; r₁r₂r₃ = −d/a.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d7', 'CO-MAT-01271', 3, 163, 'medio', 5, 63, 2026, 'multiple_choice', 'Relações de Girard', 'Sejam r₁, r₂ e r₃ as raízes (reais ou complexas) da equação x³ − 9x² + x + 11 = 0. Qual é a produto das raízes?', 'Pelas relações de Girard para ax³ + bx² + cx + d = 0: soma = −b/a, soma dos produtos dois a dois = c/a, produto = −d/a. Aqui a = 1, b = -9, c = 1, d = 11, então a produto é −11.', 'Girard: r₁ + r₂ + r₃ = −b/a; r₁r₂ + r₁r₃ + r₂r₃ = c/a; r₁r₂r₃ = −d/a.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d8', 'CO-MAT-01272', 3, 163, 'medio', 5, 63, 2026, 'multiple_choice', 'Relações de Girard', 'Sejam r₁, r₂ e r₃ as raízes (reais ou complexas) da equação x³ − 2x² − 8x − 7 = 0. Qual é a soma das raízes?', 'Pelas relações de Girard para ax³ + bx² + cx + d = 0: soma = −b/a, soma dos produtos dois a dois = c/a, produto = −d/a. Aqui a = 1, b = -2, c = -8, d = -7, então a soma é 2.', 'Girard: r₁ + r₂ + r₃ = −b/a; r₁r₂ + r₁r₃ + r₂r₃ = c/a; r₁r₂r₃ = −d/a.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012d9', 'CO-MAT-01273', 3, 163, 'medio', 5, 63, 2026, 'multiple_choice', 'Relações de Girard', 'Sejam r₁, r₂ e r₃ as raízes (reais ou complexas) da equação −4x³ + 7x² − 2x − 5 = 0. Qual é a soma dos produtos dois a dois das raízes?', 'Pelas relações de Girard para ax³ + bx² + cx + d = 0: soma = −b/a, soma dos produtos dois a dois = c/a, produto = −d/a. Aqui a = -4, b = 7, c = -2, d = -5, então a soma dos produtos dois a dois é 1/2.', 'Girard: r₁ + r₂ + r₃ = −b/a; r₁r₂ + r₁r₃ + r₂r₃ = c/a; r₁r₂r₃ = −d/a.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012da', 'CO-MAT-01274', 3, 164, 'medio', 4, 63, 2026, 'multiple_choice', 'Área de triângulo', 'Qual é a área do triângulo de vértices A(0, 6), B(5, 2) e C(1, −3)?', 'A área é |D|/2, onde D é o determinante com as coordenadas: D = −41. Área = 41/2 = 20,5.', 'Monte o determinante com x, y e 1 de cada vértice; a área é metade do módulo.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012db', 'CO-MAT-01275', 3, 164, 'medio', 4, 63, 2026, 'multiple_choice', 'Área de triângulo', 'Qual é a área do triângulo de vértices A(6, 1), B(5, −1) e C(−3, 7)?', 'A área é |D|/2, onde D é o determinante com as coordenadas: D = −24. Área = 24/2 = 12.', 'Monte o determinante com x, y e 1 de cada vértice; a área é metade do módulo.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012dc', 'CO-MAT-01276', 3, 164, 'medio', 4, 63, 2026, 'multiple_choice', 'Área de triângulo', 'Qual é a área do triângulo de vértices A(−2, −3), B(6, 4) e C(−5, −5)?', 'A área é |D|/2, onde D é o determinante com as coordenadas: D = 5. Área = 5/2 = 2,5.', 'Monte o determinante com x, y e 1 de cada vértice; a área é metade do módulo.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012dd', 'CO-MAT-01277', 3, 164, 'medio', 4, 63, 2026, 'multiple_choice', 'Área de triângulo', 'Qual é a área do triângulo de vértices A(−3, 2), B(5, 1) e C(4, −2)?', 'A área é |D|/2, onde D é o determinante com as coordenadas: D = −25. Área = 25/2 = 12,5.', 'Monte o determinante com x, y e 1 de cada vértice; a área é metade do módulo.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012de', 'CO-MAT-01278', 3, 164, 'medio', 4, 63, 2026, 'multiple_choice', 'Área de triângulo', 'Qual é a área do triângulo de vértices A(−2, −1), B(2, 3) e C(3, 6)?', 'A área é |D|/2, onde D é o determinante com as coordenadas: D = 8. Área = 8/2 = 4.', 'Monte o determinante com x, y e 1 de cada vértice; a área é metade do módulo.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012df', 'CO-MAT-01279', 3, 164, 'medio', 4, 63, 2026, 'multiple_choice', 'Área de triângulo', 'Qual é a área do triângulo de vértices A(2, 1), B(3, 2) e C(−4, 1)?', 'A área é |D|/2, onde D é o determinante com as coordenadas: D = 6. Área = 6/2 = 3.', 'Monte o determinante com x, y e 1 de cada vértice; a área é metade do módulo.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e0', 'CO-MAT-01280', 3, 165, 'enem', 2, 63, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Nicolas gasta R$ 360,00 para produzir uma camiseta estampada e quer ter lucro de 25% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 25% de R$ 360,00 = R$ 90,00. Preço de venda: R$ 360,00 × 1,25 = R$ 450,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e1', 'CO-MAT-01281', 3, 165, 'enem', 2, 63, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Lucas gasta R$ 250,00 para produzir um vaso de planta e quer ter lucro de 50% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 50% de R$ 250,00 = R$ 125,00. Preço de venda: R$ 250,00 × 1,5 = R$ 375,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e2', 'CO-MAT-01282', 3, 165, 'enem', 2, 63, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Júlia gasta R$ 45,00 para produzir uma capinha de celular e quer ter lucro de 20% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 20% de R$ 45,00 = R$ 9,00. Preço de venda: R$ 45,00 × 1,2 = R$ 54,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e3', 'CO-MAT-01283', 3, 165, 'enem', 2, 63, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Yasmin gasta R$ 220,00 para produzir um kit de maquiagem e quer ter lucro de 10% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 10% de R$ 220,00 = R$ 22,00. Preço de venda: R$ 220,00 × 1,1 = R$ 242,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e4', 'CO-MAT-01284', 3, 165, 'enem', 2, 63, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Amanda gasta R$ 210,00 para produzir uma capinha de celular e quer ter lucro de 40% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 40% de R$ 210,00 = R$ 84,00. Preço de venda: R$ 210,00 × 1,4 = R$ 294,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e5', 'CO-MAT-01285', 3, 165, 'enem', 2, 63, 2026, 'multiple_choice', 'Lucro e prejuízo', 'Samuel gasta R$ 160,00 para produzir um bolo de pote e quer ter lucro de 25% sobre o custo. Por quanto deve vender cada unidade?', 'Lucro: 25% de R$ 160,00 = R$ 40,00. Preço de venda: R$ 160,00 × 1,25 = R$ 200,00.', 'Preço = custo × (1 + taxa de lucro).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e6', 'CO-MAT-01286', 3, 166, 'medio', 4, 63, 2026, 'multiple_choice', 'Variância e desvio padrão', 'As notas de um grupo foram: 9, 12, 11, 8. Qual é a variância (populacional) dessas notas?', 'Média = 10. Desvios: -2, 2, -1, 1. Quadrados: 4, 4, 1, 1. Variância = 10/4 = 2,5. (O desvio padrão seria √2,5.)', 'Variância = média dos quadrados dos desvios em relação à média.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e7', 'CO-MAT-01287', 3, 166, 'medio', 4, 63, 2026, 'multiple_choice', 'Variância e desvio padrão', 'As notas de um grupo foram: 12, 15, 9, 9, 6, 3. Qual é a variância (populacional) dessas notas?', 'Média = 9. Desvios: -6, 6, 0, 0, -3, 3. Quadrados: 36, 36, 0, 0, 9, 9. Variância = 90/6 = 15. (O desvio padrão seria √15.)', 'Variância = média dos quadrados dos desvios em relação à média.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e8', 'CO-MAT-01288', 3, 166, 'medio', 4, 63, 2026, 'multiple_choice', 'Variância e desvio padrão', 'As notas de um grupo foram: 19, 19, 22, 16. Qual é a variância (populacional) dessas notas?', 'Média = 19. Desvios: -3, 3, 0, 0. Quadrados: 9, 9, 0, 0. Variância = 18/4 = 4,5. (O desvio padrão seria √4,5.)', 'Variância = média dos quadrados dos desvios em relação à média.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012e9', 'CO-MAT-01289', 3, 166, 'medio', 4, 63, 2026, 'multiple_choice', 'Variância e desvio padrão', 'As notas de um grupo foram: 17, 23, 20, 20. Qual é a variância (populacional) dessas notas?', 'Média = 20. Desvios: -3, 3, 0, 0. Quadrados: 9, 9, 0, 0. Variância = 18/4 = 4,5. (O desvio padrão seria √4,5.)', 'Variância = média dos quadrados dos desvios em relação à média.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ea', 'CO-MAT-01290', 3, 166, 'medio', 4, 63, 2026, 'multiple_choice', 'Variância e desvio padrão', 'As notas de um grupo foram: 18, 15, 19, 20. Qual é a variância (populacional) dessas notas?', 'Média = 18. Desvios: -3, 1, 2, 0. Quadrados: 9, 1, 4, 0. Variância = 14/4 = 3,5. (O desvio padrão seria √3,5.)', 'Variância = média dos quadrados dos desvios em relação à média.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012eb', 'CO-MAT-01291', 3, 166, 'medio', 4, 63, 2026, 'multiple_choice', 'Variância e desvio padrão', 'As notas de um grupo foram: 12, 12, 8, 8. Qual é a variância (populacional) dessas notas?', 'Média = 10. Desvios: -2, -2, 2, 2. Quadrados: 4, 4, 4, 4. Variância = 16/4 = 4. (O desvio padrão seria √4.)', 'Variância = média dos quadrados dos desvios em relação à média.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ec', 'CO-MAT-01292', 3, 167, 'medio', 3, 63, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = 4x + 6, qual é o valor de f⁻¹(2)?', 'f⁻¹(2) é o x tal que f(x) = 2: 4x  + 6 = 2 ⇒ x = −1.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ed', 'CO-MAT-01293', 3, 167, 'medio', 3, 63, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = 2x + 3, qual é o valor de f⁻¹(1)?', 'f⁻¹(1) é o x tal que f(x) = 1: 2x  + 3 = 1 ⇒ x = −1.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ee', 'CO-MAT-01294', 3, 167, 'medio', 3, 63, 2026, 'multiple_choice', 'Composição e inversa', 'Dadas as funções f(x) = x + 7 e g(x) = −3x − 1, o valor de f(g(0)) é:', 'Primeiro g(0) = −1. Depois f(−1) = 6.', 'Na composta f(g(x)), calcule primeiro a função de dentro.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ef', 'CO-MAT-01295', 3, 167, 'medio', 3, 63, 2026, 'multiple_choice', 'Composição e inversa', 'Dadas as funções f(x) = 2x + 1 e g(x) = 2x − 4, o valor de f(g(5)) é:', 'Primeiro g(5) = 6. Depois f(6) = 13.', 'Na composta f(g(x)), calcule primeiro a função de dentro.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f0', 'CO-MAT-01296', 3, 167, 'medio', 3, 63, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = −5x + 3, qual é o valor de f⁻¹(−17)?', 'f⁻¹(−17) é o x tal que f(x) = −17: −5x  + 3 = −17 ⇒ x = 4.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f1', 'CO-MAT-01297', 3, 167, 'medio', 3, 63, 2026, 'multiple_choice', 'Composição e inversa', 'Dadas as funções f(x) = −3x + 5 e g(x) = 2x − 6, o valor de f(g(4)) é:', 'Primeiro g(4) = 2. Depois f(2) = −1.', 'Na composta f(g(x)), calcule primeiro a função de dentro.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f2', 'CO-MAT-01298', 3, 167, 'medio', 3, 63, 2026, 'multiple_choice', 'Composição e inversa', 'Sendo f(x) = −2x − 3, qual é o valor de f⁻¹(5)?', 'f⁻¹(5) é o x tal que f(x) = 5: −2x  − 3 = 5 ⇒ x = −4.', 'f⁻¹(y) é o número que, colocado em f, dá y.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f3', 'CO-MAT-01299', 3, 168, 'medio', 2, 63, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (4,2 × 10¹) · (2,5 × 10⁰), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 4,2 · 2,5 = 10,5 e 10¹ · 10⁰ = 10¹. Ajustando para mantissa entre 1 e 10: 1,05 × 10².', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f4', 'CO-MAT-01300', 3, 168, 'medio', 2, 63, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (3,3 × 10⁵) · (2 × 10¹), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 3,3 · 2 = 6,6 e 10⁵ · 10¹ = 10⁶. Ajustando para mantissa entre 1 e 10: 6,6 × 10⁶.', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f5', 'CO-MAT-01301', 3, 168, 'medio', 2, 63, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (7,5 × 10⁻⁴) · (3 × 10⁵), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 7,5 · 3 = 22,5 e 10⁻⁴ · 10⁵ = 10¹. Ajustando para mantissa entre 1 e 10: 2,25 × 10².', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f6', 'CO-MAT-01302', 3, 168, 'medio', 2, 63, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (6,4 × 10³) · (4 × 10¹), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 6,4 · 4 = 25,6 e 10³ · 10¹ = 10⁴. Ajustando para mantissa entre 1 e 10: 2,56 × 10⁵.', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f7', 'CO-MAT-01303', 3, 168, 'medio', 2, 63, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (3,3 × 10⁻⁶) · (1,5 × 10⁵), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 3,3 · 1,5 = 4,95 e 10⁻⁶ · 10⁵ = 10⁻¹. Ajustando para mantissa entre 1 e 10: 4,95 × 10⁻¹.', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f8', 'CO-MAT-01304', 3, 168, 'medio', 2, 63, 2026, 'multiple_choice', 'Notação científica', 'O resultado de (7,3 × 10⁻³) · (5 × 10⁷), em notação científica, é:', 'Multiplica-se as mantissas e somam-se os expoentes: 7,3 · 5 = 36,5 e 10⁻³ · 10⁷ = 10⁴. Ajustando para mantissa entre 1 e 10: 3,65 × 10⁵.', 'Multiplique os números da frente e some os expoentes de 10.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012f9', 'CO-MAT-01305', 3, 169, 'medio', 3, 63, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 5^(−2x + 5) = 5?', '5 = 5¹. Igualando os expoentes: −2x + 5 = 1 ⇒ x = 2.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012fa', 'CO-MAT-01306', 3, 169, 'medio', 3, 63, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 5^(−3x − 2) = 78.125?', '78.125 = 5⁷. Igualando os expoentes: −3x − 2 = 7 ⇒ x = −3.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012fb', 'CO-MAT-01307', 3, 169, 'medio', 3, 63, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 3^(−2x + 1) = 2.187?', '2.187 = 3⁷. Igualando os expoentes: −2x + 1 = 7 ⇒ x = −3.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012fc', 'CO-MAT-01308', 3, 169, 'medio', 3, 63, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 3^(3x + 4) = 81?', '81 = 3⁴. Igualando os expoentes: 3x + 4 = 4 ⇒ x = 0.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012fd', 'CO-MAT-01309', 3, 169, 'medio', 3, 63, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 2^(−2x − 4) = 1/64?', '1/64 = 2⁻⁶. Igualando os expoentes: −2x − 4 = −6 ⇒ x = 1.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012fe', 'CO-MAT-01310', 3, 169, 'medio', 3, 63, 2026, 'multiple_choice', 'Equações exponenciais', 'Qual é o valor de x que satisfaz 2^(−2x − 5) = 2?', '2 = 2¹. Igualando os expoentes: −2x − 5 = 1 ⇒ x = −3.', 'Escreva os dois lados na mesma base e iguale os expoentes.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-0000000012ff', 'CO-FIS-00161', 6, 170, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento uniformemente variado', 'Um ônibus parte com velocidade de 7 m/s e acelera uniformemente a 3 m/s². Qual é sua velocidade após 10 s?', 'v = v₀ + a·t = 7 + 3·10 = 37 m/s.', 'No MUV, a velocidade muda a cada segundo o valor da aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001300', 'CO-FIS-00162', 6, 170, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento uniformemente variado', 'Um carro parte com velocidade de 18 m/s e acelera uniformemente a 4 m/s². Qual é sua velocidade após 4 s?', 'v = v₀ + a·t = 18 + 4·4 = 34 m/s.', 'No MUV, a velocidade muda a cada segundo o valor da aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001301', 'CO-FIS-00163', 6, 170, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento uniformemente variado', 'Um ônibus parte com velocidade de 2 m/s e acelera uniformemente a 4 m/s². Qual é sua velocidade após 10 s?', 'v = v₀ + a·t = 2 + 4·10 = 42 m/s.', 'No MUV, a velocidade muda a cada segundo o valor da aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001302', 'CO-FIS-00164', 6, 170, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento uniformemente variado', 'Um ônibus parte com velocidade de 11 m/s e acelera uniformemente a 1 m/s². Qual é sua velocidade após 10 s?', 'v = v₀ + a·t = 11 + 1·10 = 21 m/s.', 'No MUV, a velocidade muda a cada segundo o valor da aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001303', 'CO-FIS-00165', 6, 170, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento uniformemente variado', 'Um carro parte com velocidade de 15 m/s e acelera uniformemente a 5 m/s². Qual é sua velocidade após 3 s?', 'v = v₀ + a·t = 15 + 5·3 = 30 m/s.', 'No MUV, a velocidade muda a cada segundo o valor da aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001304', 'CO-FIS-00166', 6, 170, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento uniformemente variado', 'Um patinete parte com velocidade de 4 m/s e acelera uniformemente a 6 m/s². Qual é sua velocidade após 2 s?', 'v = v₀ + a·t = 4 + 6·2 = 16 m/s.', 'No MUV, a velocidade muda a cada segundo o valor da aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001305', 'CO-FIS-00167', 6, 174, 'enem', 3, 63, 2026, 'multiple_choice', 'Trabalho e potência', 'Um guindaste ergue, com velocidade constante, uma carga de 70 kg a uma altura de 12 m em 50 s. Usando g = 10 m/s², qual a potência média desenvolvida?', 'Trabalho = m·g·h = 70·10·12 = 8.400 J. Potência = trabalho/tempo = 8.400/50 = 168 W.', 'Potência é energia por tempo: P = m·g·h/t.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001306', 'CO-FIS-00168', 6, 174, 'enem', 3, 63, 2026, 'multiple_choice', 'Trabalho e potência', 'Um guindaste ergue, com velocidade constante, uma carga de 170 kg a uma altura de 2 m em 5 s. Usando g = 10 m/s², qual a potência média desenvolvida?', 'Trabalho = m·g·h = 170·10·2 = 3.400 J. Potência = trabalho/tempo = 3.400/5 = 680 W.', 'Potência é energia por tempo: P = m·g·h/t.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001307', 'CO-FIS-00169', 6, 174, 'enem', 3, 63, 2026, 'multiple_choice', 'Trabalho e potência', 'Um guindaste ergue, com velocidade constante, uma carga de 80 kg a uma altura de 13 m em 20 s. Usando g = 10 m/s², qual a potência média desenvolvida?', 'Trabalho = m·g·h = 80·10·13 = 10.400 J. Potência = trabalho/tempo = 10.400/20 = 520 W.', 'Potência é energia por tempo: P = m·g·h/t.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001308', 'CO-FIS-00170', 6, 174, 'enem', 3, 63, 2026, 'multiple_choice', 'Trabalho e potência', 'Um guindaste ergue, com velocidade constante, uma carga de 180 kg a uma altura de 6 m em 10 s. Usando g = 10 m/s², qual a potência média desenvolvida?', 'Trabalho = m·g·h = 180·10·6 = 10.800 J. Potência = trabalho/tempo = 10.800/10 = 1.080 W.', 'Potência é energia por tempo: P = m·g·h/t.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001309', 'CO-FIS-00171', 6, 174, 'enem', 3, 63, 2026, 'multiple_choice', 'Trabalho e potência', 'Um guindaste ergue, com velocidade constante, uma carga de 200 kg a uma altura de 10 m em 5 s. Usando g = 10 m/s², qual a potência média desenvolvida?', 'Trabalho = m·g·h = 200·10·10 = 20.000 J. Potência = trabalho/tempo = 20.000/5 = 4.000 W.', 'Potência é energia por tempo: P = m·g·h/t.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000130a', 'CO-FIS-00172', 6, 174, 'enem', 3, 63, 2026, 'multiple_choice', 'Trabalho e potência', 'Um guindaste ergue, com velocidade constante, uma carga de 80 kg a uma altura de 15 m em 5 s. Usando g = 10 m/s², qual a potência média desenvolvida?', 'Trabalho = m·g·h = 80·10·15 = 12.000 J. Potência = trabalho/tempo = 12.000/5 = 2.400 W.', 'Potência é energia por tempo: P = m·g·h/t.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000130b', 'CO-FIS-00173', 6, 175, 'medio', 4, 63, 2026, 'multiple_choice', 'Quantidade de movimento', 'Um carrinho de 900 kg, a 16 m/s, colide com outro de 600 kg, parado. Após a colisão, eles seguem juntos. Desprezando atritos, qual a velocidade do conjunto logo após a batida?', 'Conservação da quantidade de movimento: 900·16 = (900 + 600)·v ⇒ v = 14400/1500 = 9,6 m/s.', 'Numa colisão, a quantidade de movimento total (m·v) se conserva.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000130c', 'CO-FIS-00174', 6, 175, 'medio', 4, 63, 2026, 'multiple_choice', 'Quantidade de movimento', 'Um carrinho de 100 kg, a 5 m/s, colide com outro de 400 kg, parado. Após a colisão, eles seguem juntos. Desprezando atritos, qual a velocidade do conjunto logo após a batida?', 'Conservação da quantidade de movimento: 100·5 = (100 + 400)·v ⇒ v = 500/500 = 1 m/s.', 'Numa colisão, a quantidade de movimento total (m·v) se conserva.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000130d', 'CO-FIS-00175', 6, 175, 'medio', 4, 63, 2026, 'multiple_choice', 'Quantidade de movimento', 'Um carrinho de 200 kg, a 2 m/s, colide com outro de 300 kg, parado. Após a colisão, eles seguem juntos. Desprezando atritos, qual a velocidade do conjunto logo após a batida?', 'Conservação da quantidade de movimento: 200·2 = (200 + 300)·v ⇒ v = 400/500 = 0,8 m/s.', 'Numa colisão, a quantidade de movimento total (m·v) se conserva.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000130e', 'CO-FIS-00176', 6, 175, 'medio', 4, 63, 2026, 'multiple_choice', 'Quantidade de movimento', 'Um carrinho de 600 kg, a 20 m/s, colide com outro de 900 kg, parado. Após a colisão, eles seguem juntos. Desprezando atritos, qual a velocidade do conjunto logo após a batida?', 'Conservação da quantidade de movimento: 600·20 = (600 + 900)·v ⇒ v = 12000/1500 = 8 m/s.', 'Numa colisão, a quantidade de movimento total (m·v) se conserva.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000130f', 'CO-FIS-00177', 6, 175, 'medio', 4, 63, 2026, 'multiple_choice', 'Quantidade de movimento', 'Um carrinho de 400 kg, a 3 m/s, colide com outro de 800 kg, parado. Após a colisão, eles seguem juntos. Desprezando atritos, qual a velocidade do conjunto logo após a batida?', 'Conservação da quantidade de movimento: 400·3 = (400 + 800)·v ⇒ v = 1200/1200 = 1 m/s.', 'Numa colisão, a quantidade de movimento total (m·v) se conserva.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001310', 'CO-FIS-00178', 6, 175, 'medio', 4, 63, 2026, 'multiple_choice', 'Quantidade de movimento', 'Um carrinho de 100 kg, a 9 m/s, colide com outro de 200 kg, parado. Após a colisão, eles seguem juntos. Desprezando atritos, qual a velocidade do conjunto logo após a batida?', 'Conservação da quantidade de movimento: 100·9 = (100 + 200)·v ⇒ v = 900/300 = 3 m/s.', 'Numa colisão, a quantidade de movimento total (m·v) se conserva.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001311', 'CO-FIS-00179', 6, 176, 'medio', 2, 63, 2026, 'multiple_choice', 'Lei de Hooke', 'Uma mola de constante 1.800 N/m sustenta um peso de 360 N em equilíbrio. Quanto ela se deforma?', 'Lei de Hooke: F = k·x, com x em metros. 20 cm = 0,2 m; F = 1.800·0,2 = 360 N.', 'F = k·x, sempre com x em metros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001312', 'CO-FIS-00180', 6, 176, 'medio', 2, 63, 2026, 'multiple_choice', 'Lei de Hooke', 'Uma mola de constante elástica 400 N/m é esticada em 2 cm. Qual é a força elástica?', 'Lei de Hooke: F = k·x, com x em metros. 2 cm = 0,02 m; F = 400·0,02 = 8 N.', 'F = k·x, sempre com x em metros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001313', 'CO-FIS-00181', 6, 176, 'medio', 2, 63, 2026, 'multiple_choice', 'Lei de Hooke', 'Uma mola de constante elástica 1.850 N/m é esticada em 4 cm. Qual é a força elástica?', 'Lei de Hooke: F = k·x, com x em metros. 4 cm = 0,04 m; F = 1.850·0,04 = 74 N.', 'F = k·x, sempre com x em metros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001314', 'CO-FIS-00182', 6, 176, 'medio', 2, 63, 2026, 'multiple_choice', 'Lei de Hooke', 'Uma mola de constante elástica 300 N/m é esticada em 8 cm. Qual é a força elástica?', 'Lei de Hooke: F = k·x, com x em metros. 8 cm = 0,08 m; F = 300·0,08 = 24 N.', 'F = k·x, sempre com x em metros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001315', 'CO-FIS-00183', 6, 176, 'medio', 2, 63, 2026, 'multiple_choice', 'Lei de Hooke', 'Uma mola de constante 1.200 N/m sustenta um peso de 120 N em equilíbrio. Quanto ela se deforma?', 'Lei de Hooke: F = k·x, com x em metros. 10 cm = 0,1 m; F = 1.200·0,1 = 120 N.', 'F = k·x, sempre com x em metros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001316', 'CO-FIS-00184', 6, 176, 'medio', 2, 63, 2026, 'multiple_choice', 'Lei de Hooke', 'Uma mola de constante 1.200 N/m sustenta um peso de 108 N em equilíbrio. Quanto ela se deforma?', 'Lei de Hooke: F = k·x, com x em metros. 9 cm = 0,09 m; F = 1.200·0,09 = 108 N.', 'F = k·x, sempre com x em metros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001317', 'CO-FIS-00185', 6, 179, 'medio', 4, 63, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 4 atm, ocupa 2 L e tem temperatura de -73 °C. Ele passa a 5 atm e 3 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = -73 + 273 = 200 K. T₂ = 5·3·200/(4·2) = 375 K = 102 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001318', 'CO-FIS-00186', 6, 179, 'medio', 4, 63, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 5 atm, ocupa 18 L e tem temperatura de 77 °C. Ele passa a 6 atm e 18 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 77 + 273 = 350 K. T₂ = 6·18·350/(5·18) = 420 K = 147 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001319', 'CO-FIS-00187', 6, 179, 'medio', 4, 63, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 4 atm, ocupa 8 L e tem temperatura de 27 °C. Ele passa a 4 atm e 12 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 27 + 273 = 300 K. T₂ = 4·12·300/(4·8) = 450 K = 177 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000131a', 'CO-FIS-00188', 6, 179, 'medio', 4, 63, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 4 atm, ocupa 3 L e tem temperatura de 0 °C. Ele passa a 6 atm e 12 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 0 + 273 = 273 K. T₂ = 6·12·273/(4·3) = 1638 K = 1365 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000131b', 'CO-FIS-00189', 6, 179, 'medio', 4, 63, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 5 atm, ocupa 10 L e tem temperatura de 77 °C. Ele passa a 6 atm e 17 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 77 + 273 = 350 K. T₂ = 6·17·350/(5·10) = 714 K = 441 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000131c', 'CO-FIS-00190', 6, 179, 'medio', 4, 63, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 2 atm, ocupa 3 L e tem temperatura de 0 °C. Ele passa a 2 atm e 6 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 0 + 273 = 273 K. T₂ = 2·6·273/(2·3) = 546 K = 273 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000131d', 'CO-FIS-00191', 6, 179, 'medio', 4, 63, 2026, 'multiple_choice', 'Gases ideais', 'Um gás ideal está a 3 atm, ocupa 4 L e tem temperatura de 177 °C. Ele passa a 4 atm e 15 L. Qual é a nova temperatura, em °C?', 'p₁V₁/T₁ = p₂V₂/T₂, com T em kelvin. T₁ = 177 + 273 = 450 K. T₂ = 4·15·450/(3·4) = 2250 K = 1977 °C.', 'Na lei geral dos gases, use sempre temperatura em kelvin (°C + 273).', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000131e', 'CO-FIS-00192', 6, 180, 'medio', 3, 63, 2026, 'multiple_choice', 'Dilatação térmica', 'Um trilho de latão tem 180 m a 20 °C. Sendo o coeficiente de dilatação linear 1,9 × 10⁻⁵ °C⁻¹, quanto ele aumenta se a temperatura subir 90 °C?', 'ΔL = L₀·α·ΔT = 180 m · 1,9×10⁻⁵ °C⁻¹ · 90 °C = 307,8 mm (1 m = 1.000 mm). Por isso os trilhos têm pequenas folgas.', 'ΔL = L₀·α·ΔT; depois converta metros para milímetros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000131f', 'CO-FIS-00193', 6, 180, 'medio', 3, 63, 2026, 'multiple_choice', 'Dilatação térmica', 'Um trilho de aço tem 50 m a 20 °C. Sendo o coeficiente de dilatação linear 1,2 × 10⁻⁵ °C⁻¹, quanto ele aumenta se a temperatura subir 50 °C?', 'ΔL = L₀·α·ΔT = 50 m · 1,2×10⁻⁵ °C⁻¹ · 50 °C = 30 mm (1 m = 1.000 mm). Por isso os trilhos têm pequenas folgas.', 'ΔL = L₀·α·ΔT; depois converta metros para milímetros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001320', 'CO-FIS-00194', 6, 180, 'medio', 3, 63, 2026, 'multiple_choice', 'Dilatação térmica', 'Um trilho de alumínio tem 100 m a 20 °C. Sendo o coeficiente de dilatação linear 2,4 × 10⁻⁵ °C⁻¹, quanto ele aumenta se a temperatura subir 30 °C?', 'ΔL = L₀·α·ΔT = 100 m · 2,4×10⁻⁵ °C⁻¹ · 30 °C = 72 mm (1 m = 1.000 mm). Por isso os trilhos têm pequenas folgas.', 'ΔL = L₀·α·ΔT; depois converta metros para milímetros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001321', 'CO-FIS-00195', 6, 180, 'medio', 3, 63, 2026, 'multiple_choice', 'Dilatação térmica', 'Um trilho de cobre tem 10 m a 20 °C. Sendo o coeficiente de dilatação linear 1,7 × 10⁻⁵ °C⁻¹, quanto ele aumenta se a temperatura subir 100 °C?', 'ΔL = L₀·α·ΔT = 10 m · 1,7×10⁻⁵ °C⁻¹ · 100 °C = 17 mm (1 m = 1.000 mm). Por isso os trilhos têm pequenas folgas.', 'ΔL = L₀·α·ΔT; depois converta metros para milímetros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001322', 'CO-FIS-00196', 6, 180, 'medio', 3, 63, 2026, 'multiple_choice', 'Dilatação térmica', 'Um trilho de cobre tem 40 m a 20 °C. Sendo o coeficiente de dilatação linear 1,7 × 10⁻⁵ °C⁻¹, quanto ele aumenta se a temperatura subir 50 °C?', 'ΔL = L₀·α·ΔT = 40 m · 1,7×10⁻⁵ °C⁻¹ · 50 °C = 34 mm (1 m = 1.000 mm). Por isso os trilhos têm pequenas folgas.', 'ΔL = L₀·α·ΔT; depois converta metros para milímetros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001323', 'CO-FIS-00197', 6, 180, 'medio', 3, 63, 2026, 'multiple_choice', 'Dilatação térmica', 'Um trilho de alumínio tem 20 m a 20 °C. Sendo o coeficiente de dilatação linear 2,4 × 10⁻⁵ °C⁻¹, quanto ele aumenta se a temperatura subir 30 °C?', 'ΔL = L₀·α·ΔT = 20 m · 2,4×10⁻⁵ °C⁻¹ · 30 °C = 14,4 mm (1 m = 1.000 mm). Por isso os trilhos têm pequenas folgas.', 'ΔL = L₀·α·ΔT; depois converta metros para milímetros.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001324', 'CO-FIS-00198', 6, 182, 'medio', 4, 63, 2026, 'multiple_choice', 'Lentes e espelhos esféricos', 'Um objeto é colocado a 18 cm de uma lente convergente de distância focal 14 cm. A que distância da lente se forma a imagem nítida?', 'Equação de Gauss: 1/f = 1/p + 1/p'' ⇒ 1/p'' = 1/14 − 1/18 ⇒ p'' = 63 cm. Aumento: A = −p''/p = −3,5 (imagem real e invertida).', 'Use 1/f = 1/p + 1/p''.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001325', 'CO-FIS-00199', 6, 182, 'medio', 4, 63, 2026, 'multiple_choice', 'Lentes e espelhos esféricos', 'Um objeto é colocado a 84 cm de uma lente convergente de distância focal 36 cm. A que distância da lente se forma a imagem nítida?', 'Equação de Gauss: 1/f = 1/p + 1/p'' ⇒ 1/p'' = 1/36 − 1/84 ⇒ p'' = 63 cm. Aumento: A = −p''/p = −0,75 (imagem real e invertida).', 'Use 1/f = 1/p + 1/p''.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001326', 'CO-FIS-00200', 6, 182, 'medio', 4, 63, 2026, 'multiple_choice', 'Lentes e espelhos esféricos', 'Um objeto é colocado a 75 cm de uma lente convergente de distância focal 50 cm. A que distância da lente se forma a imagem nítida?', 'Equação de Gauss: 1/f = 1/p + 1/p'' ⇒ 1/p'' = 1/50 − 1/75 ⇒ p'' = 150 cm. Aumento: A = −p''/p = −2 (imagem real e invertida).', 'Use 1/f = 1/p + 1/p''.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001327', 'CO-FIS-00201', 6, 182, 'medio', 4, 63, 2026, 'multiple_choice', 'Lentes e espelhos esféricos', 'Um objeto é colocado a 32 cm de uma lente convergente de distância focal 24 cm. A que distância da lente se forma a imagem nítida?', 'Equação de Gauss: 1/f = 1/p + 1/p'' ⇒ 1/p'' = 1/24 − 1/32 ⇒ p'' = 96 cm. Aumento: A = −p''/p = −3 (imagem real e invertida).', 'Use 1/f = 1/p + 1/p''.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001328', 'CO-FIS-00202', 6, 182, 'medio', 4, 63, 2026, 'multiple_choice', 'Lentes e espelhos esféricos', 'Um objeto é colocado a 68 cm de uma lente convergente de distância focal 34 cm. A que distância da lente se forma a imagem nítida?', 'Equação de Gauss: 1/f = 1/p + 1/p'' ⇒ 1/p'' = 1/34 − 1/68 ⇒ p'' = 68 cm. Aumento: A = −p''/p = −1 (imagem real e invertida).', 'Use 1/f = 1/p + 1/p''.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001329', 'CO-FIS-00203', 6, 182, 'medio', 4, 63, 2026, 'multiple_choice', 'Lentes e espelhos esféricos', 'Um objeto é colocado a 66 cm de uma lente convergente de distância focal 48 cm. A que distância da lente se forma a imagem nítida?', 'Equação de Gauss: 1/f = 1/p + 1/p'' ⇒ 1/p'' = 1/48 − 1/66 ⇒ p'' = 176 cm. Aumento: A = −p''/p = −2,67 (imagem real e invertida).', 'Use 1/f = 1/p + 1/p''.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000132a', 'CO-FIS-00204', 6, 184, 'medio', 3, 63, 2026, 'multiple_choice', 'Movimento circular', 'Um carro faz uma curva circular de raio 10 m com velocidade constante de 12 m/s. Qual é a sua aceleração centrípeta?', 'a꜀ = v²/R = 12²/10 = 14,4 m/s².', 'Aceleração centrípeta: v²/R. Força: massa vezes essa aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000132b', 'CO-FIS-00205', 6, 184, 'medio', 3, 63, 2026, 'multiple_choice', 'Movimento circular', 'Um carro faz uma curva circular de raio 10 m com velocidade constante de 13 m/s. Qual é a sua aceleração centrípeta?', 'a꜀ = v²/R = 13²/10 = 16,9 m/s².', 'Aceleração centrípeta: v²/R. Força: massa vezes essa aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000132c', 'CO-FIS-00206', 6, 184, 'medio', 3, 63, 2026, 'multiple_choice', 'Movimento circular', 'Um carro faz uma curva circular de raio 100 m com velocidade constante de 22 m/s. Qual é a sua aceleração centrípeta?', 'a꜀ = v²/R = 22²/100 = 4,84 m/s².', 'Aceleração centrípeta: v²/R. Força: massa vezes essa aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000132d', 'CO-FIS-00207', 6, 184, 'medio', 3, 63, 2026, 'multiple_choice', 'Movimento circular', 'Um carro de 800 kg faz uma curva circular de raio 25 m com velocidade constante de 29 m/s. Qual a intensidade da força centrípeta sobre ele?', 'a꜀ = v²/R = 29²/25 = 33,64 m/s². F꜀ = m·a꜀ = 800·33,64 = 26.912 N.', 'Aceleração centrípeta: v²/R. Força: massa vezes essa aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000132e', 'CO-FIS-00208', 6, 184, 'medio', 3, 63, 2026, 'multiple_choice', 'Movimento circular', 'Um carro faz uma curva circular de raio 5 m com velocidade constante de 12 m/s. Qual é a sua aceleração centrípeta?', 'a꜀ = v²/R = 12²/5 = 28,8 m/s².', 'Aceleração centrípeta: v²/R. Força: massa vezes essa aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000132f', 'CO-FIS-00209', 6, 184, 'medio', 3, 63, 2026, 'multiple_choice', 'Movimento circular', 'Um carro faz uma curva circular de raio 5 m com velocidade constante de 19 m/s. Qual é a sua aceleração centrípeta?', 'a꜀ = v²/R = 19²/5 = 72,2 m/s².', 'Aceleração centrípeta: v²/R. Força: massa vezes essa aceleração.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001330', 'CO-FIS-00210', 6, 185, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento circular uniforme', 'Um ventilador gira a 1200 rotações por minuto. Qual é o período do movimento?', 'f = 1200 rpm ÷ 60 = 20 Hz. T = 1/f = 0,05 s.', 'Para passar de rpm para Hz, divida por 60. O período é o inverso da frequência.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001331', 'CO-FIS-00211', 6, 185, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento circular uniforme', 'O tambor de uma máquina de lavar gira a 90 rotações por minuto. Qual é a frequência, em hertz?', 'f = 90 rpm ÷ 60 = 1,5 Hz. T = 1/f = 0,67 s.', 'Para passar de rpm para Hz, divida por 60. O período é o inverso da frequência.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001332', 'CO-FIS-00212', 6, 185, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento circular uniforme', 'Uma roda-gigante de brinquedo gira a 1800 rotações por minuto. Qual é a frequência, em hertz?', 'f = 1800 rpm ÷ 60 = 30 Hz. T = 1/f = 0,03 s.', 'Para passar de rpm para Hz, divida por 60. O período é o inverso da frequência.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001333', 'CO-FIS-00213', 6, 185, 'medio', 2, 63, 2026, 'multiple_choice', 'Movimento circular uniforme', 'O tambor de uma máquina de lavar gira a 240 rotações por minuto. Qual é o período do movimento?', 'f = 240 rpm ÷ 60 = 4 Hz. T = 1/f = 0,25 s.', 'Para passar de rpm para Hz, divida por 60. O período é o inverso da frequência.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001334', 'CO-FIS-00214', 6, 186, 'enem', 2, 63, 2026, 'multiple_choice', 'Rendimento', 'Um motor elétrico recebe 2.300 J de energia e transforma 345 J em energia útil. Qual é o seu rendimento?', 'Rendimento = útil/total = 345/2.300 = 0,15 = 15%. O restante (85%) é dissipado, principalmente como calor.', 'η = energia útil ÷ energia total.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001335', 'CO-FIS-00215', 6, 186, 'enem', 2, 63, 2026, 'multiple_choice', 'Rendimento', 'Um motor a combustão recebe 2.500 J de energia e transforma 2.375 J em energia útil. Qual é o seu rendimento?', 'Rendimento = útil/total = 2.375/2.500 = 0,95 = 95%. O restante (5%) é dissipado, principalmente como calor.', 'η = energia útil ÷ energia total.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
