  ('e2000000-0000-4000-a000-00000000135e', 'CO-QUI-00132', 7, 205, 'medio', 2, 63, 2026, 'multiple_choice', 'Prótons, nêutrons e elétrons', 'O íon N²⁻ (nitrogênio) tem número atômico Z = 7 e número de massa A = 14. Quantos elétrons ele possui?', 'Prótons = Z = 7. Nêutrons = A − Z = 7. Elétrons = Z − (-2) = 9 (ânion ganha elétrons).', 'Z = prótons; A = prótons + nêutrons; a carga mostra quantos elétrons foram perdidos ou ganhos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-00000000135f', 'CO-QUI-00133', 7, 205, 'medio', 2, 63, 2026, 'multiple_choice', 'Prótons, nêutrons e elétrons', 'O íon Ne²⁺ (neônio) tem número atômico Z = 10 e número de massa A = 20. Quantos prótons ele possui?', 'Prótons = Z = 10. Nêutrons = A − Z = 10. Elétrons = Z − (+2) = 8 (cátion perde elétrons).', 'Z = prótons; A = prótons + nêutrons; a carga mostra quantos elétrons foram perdidos ou ganhos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001360', 'CO-QUI-00134', 7, 205, 'medio', 2, 63, 2026, 'multiple_choice', 'Prótons, nêutrons e elétrons', 'O íon C²⁺ (carbono) tem número atômico Z = 6 e número de massa A = 12. Quantos prótons ele possui?', 'Prótons = Z = 6. Nêutrons = A − Z = 6. Elétrons = Z − (+2) = 4 (cátion perde elétrons).', 'Z = prótons; A = prótons + nêutrons; a carga mostra quantos elétrons foram perdidos ou ganhos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
  ('e2000000-0000-4000-a000-000000001361', 'CO-QUI-00135', 7, 205, 'medio', 2, 63, 2026, 'multiple_choice', 'Prótons, nêutrons e elétrons', 'O íon N⁻ (nitrogênio) tem número atômico Z = 7 e número de massa A = 14. Quantos nêutrons ele possui?', 'Prótons = Z = 7. Nêutrons = A − Z = 7. Elétrons = Z − (-1) = 8 (ânion ganha elétrons).', 'Z = prótons; A = prótons + nêutrons; a carga mostra quantos elétrons foram perdidos ou ganhos.', 'Questão autoral da Educa Mais no estilo do vestibular da UEMASUL (2026). Não é uma questão oficial.', 'published', '2026-11-28T00:00:00.000Z'),
